SELECT AVG(end_pos - pos) AS median_length
FROM variants
WHERE chrom = '22' AND sv_type = 'DEL';

SELECT v.chrom, v.pos, v.ref, v.alt FROM variants v
JOIN clinvar c ON v.id = c.variation_id
WHERE v.chrom = '19';

SELECT review_stars, COUNT(CASE WHEN is_pathogenic THEN 1 ELSE NULL END) * 100.0 / COUNT(*) AS pathogenic_percentage
FROM clinvar
GROUP BY review_stars;
